import dev.pocketllama.photo.*;
import android.content.Context;
import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.json.*;
public final class ScannerStoreTests {
 static int checks;interface Work{void run()throws Exception;}static void ok(boolean v,String m){if(!v)throw new AssertionError(m);checks++;}static void fails(Work w)throws Exception{try{w.run();throw new AssertionError("must reject");}catch(IOException|IllegalArgumentException e){checks++;}}
 public static void main(String[] args)throws Exception {
  Path root=Files.createTempDirectory("scanner-store");Context c=new Context(root.toFile());PhotoStore photos=new PhotoStore(c);DocumentStore docs=new DocumentStore(c);byte[] image="synthetic private image".getBytes(StandardCharsets.UTF_8);
  String legacy=photos.create(image,new byte[]{4,5},1000,1400);byte[] original=Files.readAllBytes(root.resolve("private-photos-v1/"+legacy+"/photo.bin"));ok(docs.list("",100).getJSONArray("items").getJSONObject(0).getBoolean("legacy"),"old photos visible before migration");ok(docs.resolve(legacy).equals(legacy),"legacy identity preserved");ok(docs.get(legacy).getJSONArray("pages").getString(0).equals(legacy),"legacy page wrapped");ok(Arrays.equals(original,Files.readAllBytes(root.resolve("private-photos-v1/"+legacy+"/photo.bin"))),"migration preserves encrypted original bytes");
  String id=docs.create(),p1=photos.create(image,new byte[]{1},1000,1400),p2=photos.create(image,new byte[]{2},1000,1400),p3=photos.create(image,new byte[]{3},1000,1400);docs.add(id,p1);docs.add(id,p2);docs.add(id,p3);docs.reorder(id,new JSONArray().put(p2).put(p1).put(p3));ok(docs.get(id).getJSONArray("pages").getString(0).equals(p2),"page order persisted");fails(()->docs.reorder(id,new JSONArray().put(p1).put(p1).put(p3)));
  photos.reserveJob(p2);docs.claim(id);fails(()->photos.reserveJob(p1));fails(()->docs.removePage(id,p3));c.manager.alive=true;photos.beginInService(p2);
  JSONObject analysis=new JSONObject().put("signature","fixture-v1").put("blocks",new JSONArray().put(new JSONObject().put("label","Text").put("complete",true).put("text","Секретный счёт 500 рублей").put("html","<p>Секретный счёт 500 рублей</p>").put("box",new JSONArray("[0,0,100,0,100,30,0,30]"))).put(new JSONObject().put("label","Table").put("complete",false)));
  photos.analysis(p2,"processing","Первая область готова",.4,analysis);ok(photos.get(p2).getString("text").contains("500 рублей"),"partial text searchable");PhotoStore reopened=new PhotoStore(c);ok(reopened.get(p2).getJSONObject("analysis").getJSONArray("blocks").getJSONObject(0).getBoolean("complete"),"completed region survives store reopen");
  c.manager.alive=false;root.resolve("private-photos-v1/active-job").toFile().setLastModified(1);JSONObject stale=docs.get(id);stale.put("updated",1);EncryptedFiles.write(root.resolve("private-documents-v1/"+id+".bin").toFile(),PhotoKey.get(c),"document/"+id,stale.toString().getBytes(StandardCharsets.UTF_8));photos.recover();docs.recover();ok(docs.get(id).getString("state").equals("interrupted"),"document recovers after process death");ok(photos.get(p2).getString("state").equals("interrupted"),"page recovers after process death");ok(photos.get(p2).getJSONObject("analysis").getJSONArray("blocks").length()==2,"unfinished and finished regions retained");ok(!photos.anyBusy(),"crashed job releases lease marker");
  ok(docs.list("500 рублей",100).getJSONArray("items").length()==1,"document search includes partial page text");
  photos.edit(p2,"Ручная правка 501 рубль");String sourceLines=photos.get(p2).getJSONArray("lines").toString();
  fails(()->docs.claim(id,"details",legacy));docs.claim(id,"details",p2);ok(docs.get(id).getString("task").equals("details")&&docs.get(id).getString("taskPage").equals(p2),"geometry task and target are encrypted and durable");photos.reserveJob(p2);photos.beginInService(p2);
  JSONObject geometry=photos.get(p2).getJSONObject("analysis").put("detection",new JSONArray());photos.geometry(p2,"processing","Уточняем рамки",.5,geometry);
  JSONObject preserved=new PhotoStore(c).get(p2);ok(preserved.getBoolean("edited")&&preserved.getString("text").equals("Ручная правка 501 рубль")&&preserved.getJSONArray("lines").toString().equals(sourceLines),"geometry checkpoints preserve edited text and text-source mapping");
  photos.geometry(p2,"interrupted","Продолжить уточнение",.5,geometry);docs.progress(id,"interrupted","Продолжить уточнение",.5);ok(!photos.anyBusy()&&docs.get(id).getString("task").equals("details"),"geometry resume keeps its task after cancellation");docs.claim(id);ok(docs.get(id).getString("task").equals("ocr")&&docs.get(id).getString("taskPage").isEmpty(),"new ordinary OCR clears the geometry scope");docs.progress(id,"ready","",0);
  docs.claim(id);long since=System.currentTimeMillis()-65000;docs.progress(id,"processing","Обрабатываем изображение",.5,"page:1:input",since);JSONObject phase=new DocumentStore(c).get(id);ok(phase.getString("phase").equals("page:1:input")&&phase.getLong("phaseStartedAt")==since,"stage and clock origin survive encrypted store reopen");docs.progress(id,"processing","Обрабатываем изображение · 50% подготовки",.5,"page:1:input",since);ok(docs.get(id).getLong("phaseStartedAt")==since,"input updates preserve the clock origin");docs.progress(id,"interrupted","Остановлено",.5);ok(!docs.get(id).has("phaseStartedAt"),"stopped jobs do not retain a running clock");
  photos.scan(p2,new JSONArray("[0.1,0.1,0.9,0.1,0.9,0.9,0.1,0.9]"),"bw");ok(!photos.get(p2).has("analysis")&&photos.get(p2).getString("text").isEmpty(),"crop invalidates analysis");ok(Arrays.equals(image,photos.image(p2,false)),"crop keeps original");photos.rotate(p2);ok(photos.get(p2).getInt("rotation")==1&&photos.get(p2).getJSONObject("scan").getString("filter").equals("bw"),"rotation keeps crop recipe");
  docs.removePage(id,p1);ok(!photos.exists(p1)&&photos.exists(p2)&&docs.get(id).getJSONArray("pages").length()==2,"remove just one page");
  // Interrupted deletion leaves a missing catalog row that can still be removed safely.
  photos.delete(p3);ok(docs.detail(id).getJSONArray("pages").getJSONObject(1).getBoolean("missing"),"missing page is reviewable");docs.removePage(id,p3);ok(docs.get(id).getJSONArray("pages").length()==1,"missing page can be detached");
  try(java.util.stream.Stream<Path> paths=Files.walk(root)){for(Path f:(Iterable<Path>)paths.filter(Files::isRegularFile)::iterator){byte[] b=Files.readAllBytes(f);ok(!new String(b,StandardCharsets.UTF_8).contains("Секретный"),"no plaintext private analysis in files");}}
  docs.delete(id);ok(!photos.exists(p2)&&photos.exists(legacy),"document deletion preserves other legacy pages");
  try(java.util.stream.Stream<Path> paths=Files.walk(root)){paths.sorted(Comparator.reverseOrder()).forEach(f->{try{Files.delete(f);}catch(Exception e){throw new RuntimeException(e);}});}System.out.println("ScannerStoreTests: "+checks+" checks passed (production stores with filesystem/Keystore test adapters)");
 }
}
